namespace ghidra.app.plugin.core.programtree;



using docking;
using docking.action;
using docking.action;

/**
 * Class for program tree actions; ensures that actions are put on a popup
 * only if the popup is over something that implements the ProgramTreeService.
 */
abstract class ProgramTreeAction : DockingAction {

	static int SINGLE_SELECTION = 0;
	static int MULTI_SELECTION = 1;

	private int selectionType;

	ProgramTreeAction(string name, string owner, KeyStroke defaultKeyBinding) : this(name, owner, defaultKeyBinding, MULTI_SELECTION)
    {
	}

	ProgramTreeAction(string name, string owner, KeyStroke defaultKeyBinding, int selectionType) : base(name, owner)
    {

		this.selectionType = selectionType;
		if (defaultKeyBinding != null) {
			setKeyBindingData(new KeyBindingData(defaultKeyBinding));
		}
		setEnabled(false);
	}

	/* @Override */
	public bool isValidContext(ActionContext context) {
		return context.getContextObject() is ProgramNode;
	}

	/* @Override */
	public bool isAddToPopup(ActionContext context) {
		return true;
	}

	/**
	 * Get the selection type associated with this action.
	 * @return the selection type
	 */
	int getSelectionType() {
		return selectionType;
	}
}
